import Synchronization

final class Cache<Key: Hashable, Value> {
    private let store = Mutex<[Key: Value]>([:])   // state inside the mutex

    func save(_ value: Value, for key: Key) {
        store.withLock { $0[key] = value }         // scoped access
    }
    func load(_ key: Key) -> Value? {
        store.withLock { $0[key] }                 // copy out
    }
}

